(()=>{'use strict';const login=()=>location.replace('/login.html');async function check(){try{const r=await fetch('/api/auth/status',{cache:'no-store'});if(!r.ok)return;const s=await r.json();if(!s.role)login()}catch{}}check();setInterval(check,30000);window.addEventListener('pageshow',check);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});document.addEventListener('DOMContentLoaded',()=>{const box=document.createElement('div');box.style.cssText='display:flex;justify-content:flex-end;gap:12px;padding:10px 18px;font-size:14px;flex-wrap:wrap';box.innerHTML='<a href="/parent.html">🔑 보호자 관리</a><button type="button" style="font:inherit;min-height:44px;border:1px solid #d8ceee;background:#f6f1ff;border-radius:12px;padding:8px 14px">🔒 잠그기</button>';document.body.append(box);box.querySelector('button').onclick=async()=>{try{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(r.ok||r.status===401)login();else alert('잠금 요청을 완료하지 못했어요. 다시 시도해 주세요.')}catch{alert('인터넷 연결 후 다시 잠가 주세요.')}}});})();
